<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Your account · Fynefield Studio</title><link rel="stylesheet" href="<?= base_url('assets/css/admin.css') ?>"></head><body class="login-body"><form class="login-card" method="post" action="<?= site_url('admin/profile') ?>"><h1>Your <span>account</span></h1><p><?= $mustChangePassword ? 'Set a new password to continue to the Studio.' : 'Update your name or password.' ?></p><?php if (session('error')): ?><div class="notice error"><?= esc(session('error')) ?></div><?php endif ?><?php if (session('success')): ?><div class="notice success"><?= esc(session('success')) ?></div><?php endif ?><?= csrf_field() ?><label>Display name<input name="name" value="<?= esc($user['name']) ?>" required></label><label>Email<input value="<?= esc($user['email']) ?>" disabled></label><label>New password<input name="password" type="password" autocomplete="new-password" minlength="12" <?= $mustChangePassword ? 'required' : '' ?>></label><button type="submit">Save</button><?php if (! $mustChangePassword): ?><p><a href="<?= site_url('admin') ?>">← Back to the Studio</a></p><?php endif ?></form></body></html>
